// ── Logo já convertido para ESC/P (gerado automaticamente) ──────────────────
const LOGO_ESCP_BASE64 = "";

// ── Nome da impressora no Windows (ajuste se necessário) ────────────────────
const NOME_IMPRESSORA = "EPSON FX-890";

// ── Conecta ao QZ Tray (chame uma vez ao iniciar o app) ─────────────────────
export async function conectar() {
  if (qz.websocket.isActive()) return;
  await qz.websocket.connect();
}

// ── Desconecta (opcional, ao fechar o app) ───────────────────────────────────
export async function desconectar() {
  if (qz.websocket.isActive()) {
    await qz.websocket.disconnect();
  }
}

// ── Função principal de impressão ────────────────────────────────────────────
/**
 * Imprime um relatório na matricial via QZ Tray.
 *
 * @param {object}   params
 * @param {string}   params.cabecalho     - Título em negrito (ex: "RELATÓRIO 05/2026")
 * @param {string[]} params.linhas        - Linhas do corpo do relatório
 * @param {boolean}  [params.comLogo]     - Imprimir logo? (padrão: true)
 * @param {boolean}  [params.avancarPagina] - Form feed no final? (padrão: true)
 */
export async function imprimirRelatorio({
  cabecalho,
  linhas = [],
  comLogo = true,
  avancarPagina = true,
}) {
  await conectar();

  const config = qz.configs.create(NOME_IMPRESSORA);

  const dados = [];

  // Reset da impressora
  dados.push({ type: "raw", format: "plain", data: "\x1b@" });

  // Logo
  if (comLogo) {
    dados.push({ type: "raw", format: "base64", data: LOGO_ESCP_BASE64 });
    dados.push({ type: "raw", format: "plain", data: "\n" });
  }

  // Cabeçalho em negrito
  if (cabecalho) {
    dados.push({ type: "raw", format: "plain", data: "\x1bE" });   // negrito ON
    dados.push({ type: "raw", format: "plain", data: cabecalho + "\r\n" });
    dados.push({ type: "raw", format: "plain", data: "\x1bF" });   // negrito OFF
  }

  // Linhas do corpo
  for (const linha of linhas) {
    dados.push({ type: "raw", format: "plain", data: linha + "\r\n" });
  }

  // Form feed (avança o papel)
  if (avancarPagina) {
    dados.push({ type: "raw", format: "plain", data: "\x0c" });
  }

  await qz.print(config, dados);
}


